func (this *OpinionCore) ParseOpinionMarket(raw any, optionalArgs ...any) any {
	// {
	//     "chainId": "56",
	//     "conditionId": "469db44df1309dac7cf9fcaa142562f3c89719d47277e095d021c1561166539a",
	//     "createdAt": 1778750719,
	//     "cutoffAt": 0,
	//     "isResolvableByAI": true,
	//     "marketId": 16565,
	//     "marketTitle": "10–15s",
	//     "noLabel": "No",
	//     "noTokenId": "48641131337815600205538397357674754469573755318952418769815647071528778171134",
	//     "questionId": "63907f471c045499f69b5ea157bdea1942f9d53b6e5e767ae69f4d148aeeefae",
	//     "quoteToken": "0x55d398326f99059fF775485246999027B3197955",
	//     "rebate": {
	//         "maker": 0.5
	//     },
	//     "resolvedAt": 1779342061,
	//     "resultTokenId": "107063188116504514729209026208703521982564071792212276771696073817845504321279",
	//     "rules": "",
	//     "slug": "how-long-will-trump-and-xi-shake-hands-when-they-meet-10-15s",
	//     "status": 4,
	//     "statusEnum": "Resolved",
	//     "volume": "50",
	//     "yesLabel": "Yes",
	//     "yesTokenId": "107063188116504514729209026208703521982564071792212276771696073817845504321279"
	// }
	eventSlug := ccxt.GetArg(optionalArgs, 0, nil)
	_ = eventSlug
	var marketId any = this.SafeString(raw, "marketId")
	var slug any = this.SafeString(raw, "slug")
	var effectiveEventSlug any = eventSlug
	if ccxt.IsTrue(ccxt.IsTrue(ccxt.IsTrue((!ccxt.IsEqual(eventSlug, nil))) && ccxt.IsTrue((!ccxt.IsEqual(slug, nil)))) && ccxt.IsTrue((ccxt.IsEqual(ccxt.GetIndexOf(slug, eventSlug), 0)))) {
		effectiveEventSlug = nil
	}
	var marketSymbol any = this.SlugToMarketSymbol(effectiveEventSlug, slug)
	var statusEnum any = this.SafeString(raw, "statusEnum")
	var active any = (ccxt.IsEqual(statusEnum, "Activated"))
	var resolved any = (ccxt.IsEqual(statusEnum, "Resolved"))
	var resultTokenId any = this.SafeString(raw, "resultTokenId")
	var hasResult any = ccxt.IsTrue(ccxt.IsTrue(resolved) && ccxt.IsTrue((!ccxt.IsEqual(resultTokenId, nil)))) && ccxt.IsTrue((!ccxt.IsEqual(resultTokenId, "")))
	var outcomeLabels any = []any{this.SafeString(raw, "yesLabel", "YES"), this.SafeString(raw, "noLabel", "NO")}
	var outcomeTokenIds any = []any{this.SafeString(raw, "yesTokenId"), this.SafeString(raw, "noTokenId")}
	var outcomes any = []any{}
	var resolvedOutcome any = nil
	for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(outcomeLabels)); i++ {
		var label any = ccxt.GetValue(outcomeLabels, i)
		var tokenId any = ccxt.GetValue(outcomeTokenIds, i)
		var outcomeHandle any = this.SlugToOutcomeSymbol(effectiveEventSlug, slug, label)
		var winner any = nil
		var settleFraction any = nil
		if ccxt.IsTrue(hasResult) {
			winner = (ccxt.IsEqual(tokenId, resultTokenId))
			settleFraction = ccxt.Ternary(ccxt.IsTrue(winner), 1, 0)
			if ccxt.IsTrue(winner) {
				resolvedOutcome = outcomeHandle
			}
		}
		ccxt.AppendToArray(&outcomes, map[string]any{
			"id":             tokenId,
			"outcomeId":      tokenId,
			"outcome":        outcomeHandle,
			"market":         marketSymbol,
			"label":          label,
			"active":         active,
			"winner":         winner,
			"settleFraction": settleFraction,
			"info":           raw,
		})
	}
	var marketResolvedOutcome any = resolvedOutcome
	// the venue sends cutoffAt 0 for markets without a scheduled cutoff - map it to
	// undefined instead of the epoch, same for the event-level end date
	var expiryTimestamp any = nil
	if ccxt.IsTrue(!ccxt.IsEqual(this.SafeInteger(raw, "cutoffAt", 0), 0)) {
		expiryTimestamp = this.SafeTimestamp(raw, "cutoffAt")
	}
	var created any = this.SafeTimestamp(raw, "createdAt")
	return map[string]any{
		"id":              marketId,
		"market":          marketSymbol,
		"base":            "USDT",
		"quote":           "USDT",
		"settle":          nil,
		"baseId":          marketId,
		"quoteId":         "USDT",
		"settleId":        nil,
		"type":            "prediction",
		"marketType":      "binary",
		"executionModel":  "clob",
		"spot":            false,
		"margin":          false,
		"swap":            false,
		"future":          false,
		"option":          false,
		"prediction":      true,
		"active":          active,
		"resolved":        resolved,
		"resolvedOutcome": marketResolvedOutcome,
		"contract":        false,
		"linear":          nil,
		"inverse":         nil,
		"contractSize":    nil,
		"expiry":          expiryTimestamp,
		"expiryDatetime":  this.Iso8601(expiryTimestamp),
		"strike":          nil,
		"optionType":      nil,
		"taker":           ccxt.GetValue(ccxt.GetValue(this.Fees, "trading"), "taker"),
		"maker":           ccxt.GetValue(ccxt.GetValue(this.Fees, "trading"), "maker"),
		"percentage":      true,
		"tierBased":       false,
		"feeSide":         "get",
		"precision": map[string]any{
			"amount": nil,
			"price":  nil,
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": 1,
				"max": 1,
			},
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"price": map[string]any{
				"min": 0,
				"max": 1,
			},
			"cost": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"outcomes": outcomes,
		"info":     raw,
		"created":  created,
	}
}

