func (this *OpinionCore) SignOpinionOrder(order any, exchangeAddress any) any {
	var domain any = map[string]any{
		"name":              "OPINION CTF Exchange",
		"version":           "1",
		"chainId":           56,
		"verifyingContract": exchangeAddress,
	}
	var messageTypes any = map[string]any{
		"Order": []any{map[string]any{
			"name": "salt",
			"type": "uint256",
		}, map[string]any{
			"name": "maker",
			"type": "address",
		}, map[string]any{
			"name": "signer",
			"type": "address",
		}, map[string]any{
			"name": "taker",
			"type": "address",
		}, map[string]any{
			"name": "tokenId",
			"type": "uint256",
		}, map[string]any{
			"name": "makerAmount",
			"type": "uint256",
		}, map[string]any{
			"name": "takerAmount",
			"type": "uint256",
		}, map[string]any{
			"name": "expiration",
			"type": "uint256",
		}, map[string]any{
			"name": "nonce",
			"type": "uint256",
		}, map[string]any{
			"name": "feeRateBps",
			"type": "uint256",
		}, map[string]any{
			"name": "side",
			"type": "uint8",
		}, map[string]any{
			"name": "signatureType",
			"type": "uint8",
		}},
	}
	var encoded any = this.EthEncodeStructuredData(domain, messageTypes, order)
	var sig any = this.SignMessage(encoded, this.PrivateKey)
	return ccxt.Add(ccxt.Add(ccxt.Add("0x", this.Remove0xPrefix(ccxt.GetValue(sig, "r"))), this.Remove0xPrefix(ccxt.GetValue(sig, "s"))), this.IntToBase16(ccxt.GetValue(sig, "v")))
}
func (this *OpinionCore) OpinionOrderRawAmounts(isMarket any, side any, amount any, price any, decimals any) any {
	var decimalsStr any = "1"
	for i := 0; ccxt.IsLessThan(i, decimals); i++ {
		decimalsStr = ccxt.Add(decimalsStr, "0")
	}
	var amountStr any = this.NumberToString(amount)
	if ccxt.IsTrue(ccxt.IsTrue(isMarket) && ccxt.IsTrue((ccxt.IsEqual(side, "BUY")))) {
		var marketMakerAmountWei any = this.DecimalToPrecision(ccxt.Precise.StringMul(amountStr, decimalsStr), ccxt.TRUNCATE, 0, ccxt.DECIMAL_PLACES)
		return map[string]any{
			"makerAmount": marketMakerAmountWei,
			"takerAmount": "0",
		}
	}
	var priceStr any = this.DecimalToPrecision(this.NumberToString(price), ccxt.ROUND, 6, ccxt.DECIMAL_PLACES)
	var priceParts any = ccxt.Split(priceStr, ".")
	var priceInt any = this.SafeString(priceParts, 0, "0")
	var priceFrac any = this.SafeString(priceParts, 1, "")
	var priceDenom any = "1000000"
	var priceNum any = ccxt.Precise.StringAdd(ccxt.Precise.StringMul(priceInt, priceDenom), ccxt.PadEnd(priceFrac, 6, "0"))
	if ccxt.IsTrue(ccxt.IsEqual(priceNum, "0")) {
		panic(ccxt.InvalidOrder(ccxt.Add(ccxt.Add(this.Id, " createOrder() invalid price "), priceStr)))
	}
	var makerRaw any = amountStr
	if ccxt.IsTrue(ccxt.IsEqual(side, "BUY")) {
		makerRaw = ccxt.Precise.StringMul(amountStr, priceStr)
	}
	var makerAmountWei any = this.DecimalToPrecision(ccxt.Precise.StringMul(makerRaw, decimalsStr), ccxt.TRUNCATE, 0, ccxt.DECIMAL_PLACES)
	var makerAmount any = nil
	var takerAmount any = nil
	if ccxt.IsTrue(ccxt.IsEqual(side, "BUY")) {
		var k any = ccxt.Precise.StringDiv(makerAmountWei, priceNum, 0)
		makerAmount = ccxt.Precise.StringMul(k, priceNum)
		takerAmount = ccxt.Precise.StringMul(k, priceDenom)
	} else {
		var k any = ccxt.Precise.StringDiv(makerAmountWei, priceDenom, 0)
		makerAmount = ccxt.Precise.StringMul(k, priceDenom)
		takerAmount = ccxt.Precise.StringMul(k, priceNum)
	}
	return map[string]any{
		"makerAmount": makerAmount,
		"takerAmount": takerAmount,
	}
}

/**
 * @method
 * @name opinion#createOrder
 * @description places a limit or market order on the CLOB for the given outcome token
 * @see https://docs.opinion.trade/developer-guide/opinion-open-api/order
 * @param {string} outcome unified outcome or outcome token id
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount for limit orders, the number of outcome shares to trade; for market orders, the quote (USDT) to spend on a BUY or the shares to sell on a SELL
 * @param {float} [price] the price per outcome token between 0 and 1; required for limit orders and market SELL orders (where it acts as the reference / worst acceptable price for the taker amount); ignored for market BUY orders (amount is already the quote to spend)
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {bool} [params.postOnly] limit orders only - reject the order if it would cross the spread
 * @returns {object} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
 */
func (this *OpinionCore) CreateOrder(outcome any, typeVar any, side any, amount any, optionalArgs ...any) <-chan any {
	ch := make(chan any)
	go func() any {
		defer close(ch)
		defer ccxt.ReturnPanicError(ch)
		price := ccxt.GetArg(optionalArgs, 0, nil)
		_ = price
		params := ccxt.GetArg(optionalArgs, 1, map[string]any{})
		_ = params

		retRes10078 := (<-this.LoadApiKey())
		ccxt.PanicOnError(retRes10078)
		this.CheckRequiredCredentials()

		outcomeObj := (<-this.LoadOutcome(outcome))
		ccxt.PanicOnError(outcomeObj)
		var tokenId any = ccxt.GetValue(outcomeObj, "outcomeId")
		var isMarket any = (ccxt.IsEqual(typeVar, "market"))
		var sideStr any = ccxt.ToUpper(side)
		if ccxt.IsTrue(ccxt.IsEqual(price, nil)) {
			if !ccxt.IsTrue(isMarket) {
				panic(ccxt.ArgumentsRequired(ccxt.Add(this.Id, " createOrder() requires a price for limit orders")))
			}
			if ccxt.IsTrue(ccxt.IsEqual(sideStr, "SELL")) {
				panic(ccxt.ArgumentsRequired(ccxt.Add(this.Id, " createOrder() requires a price for market sell orders")))
			}
		}
		var marketOrderPrice any = "0"
		if ccxt.IsTrue(ccxt.IsTrue(isMarket) && ccxt.IsTrue((ccxt.IsEqual(sideStr, "SELL")))) {
			marketOrderPrice = this.NumberToString(price)
		}
		var info any = this.SafeDict(outcomeObj, "info", map[string]any{})
		var topicId any = this.SafeInteger(info, "marketId")
		var quoteTokenAddress any = this.SafeString(info, "quoteToken")

		quoteToken := (<-this.LoadQuoteToken(quoteTokenAddress))
		ccxt.PanicOnError(quoteToken)
		var exchangeAddress any = this.SafeString(quoteToken, "ctfExchangeAddress", "")
		var decimals any = this.SafeInteger(quoteToken, "decimal", 18)
		var amounts any = this.OpinionOrderRawAmounts(isMarket, sideStr, amount, price, decimals)
		var makerAmount any = this.SafeString(amounts, "makerAmount")
		var takerAmount any = this.SafeString(amounts, "takerAmount")
		var sideInt any = ccxt.Ternary(ccxt.IsTrue((ccxt.IsEqual(sideStr, "BUY"))), 0, 1)
		var salt any = this.NumberToString(this.Milliseconds())
		var postOnly any = this.SafeBool(params, "postOnly", false)
		var rest any = this.Omit(params, []any{"postOnly"})

		maker := (<-this.LoadMultiSignAddress())
		ccxt.PanicOnError(maker)
		// Ethereum addresses are case-insensitive - a checksummed multiSignAddress compared
		// against a differently-cased walletAddress with strict equality would pick the wrong
		// signatureType (0 EOA vs 2 Gnosis Safe) and break order signing/validation
		var makerLower any = ccxt.ToLower(maker)
		var walletAddressLower any = ccxt.ToLower(this.WalletAddress)
		var signatureType any = ccxt.Ternary(ccxt.IsTrue((ccxt.IsEqual(makerLower, walletAddressLower))), 0, 2)
		var order any = map[string]any{
			"salt":          salt,
			"maker":         maker,
			"signer":        this.WalletAddress,
			"taker":         "0x0000000000000000000000000000000000000000",
			"tokenId":       tokenId,
			"makerAmount":   makerAmount,
			"takerAmount":   takerAmount,
			"expiration":    "0",
			"nonce":         "0",
			"feeRateBps":    "0",
			"side":          sideInt,
			"signatureType": signatureType,
		}
		var signature any = this.SignOpinionOrder(order, exchangeAddress)
		var signatureNo0x any = this.Remove0xPrefix(signature)
		var orderBody any = this.Extend(map[string]any{
			"salt":            salt,
			"maker":           maker,
			"signer":          this.WalletAddress,
			"taker":           "0x0000000000000000000000000000000000000000",
			"tokenId":         tokenId,
			"makerAmount":     makerAmount,
			"takerAmount":     takerAmount,
			"expiration":      "0",
			"nonce":           "0",
			"feeRateBps":      "0",
			"side":            ccxt.ToString(sideInt),
			"signatureType":   ccxt.ToString(signatureType),
			"signature":       signature,
			"sign":            ccxt.Slice(signatureNo0x, 0, 64),
			"contractAddress": "",
			"currencyAddress": quoteTokenAddress,
			"topicId":         topicId,
			"price":           ccxt.Ternary(ccxt.IsTrue(isMarket), marketOrderPrice, this.NumberToString(price)),
			"tradingMethod":   ccxt.Ternary(ccxt.IsTrue(isMarket), 1, 2),
			"timestamp":       this.Seconds(),
			"safeRate":        "0",
			"orderExpTime":    "0",
			"postOnly":        postOnly,
		}, rest)

		response := (<-this.OpinionPrivatePostOrder(orderBody))
		ccxt.PanicOnError(response)
		var result any = this.SafeDict(response, "result", map[string]any{})
		var orderData any = this.SafeDict(result, "orderData", map[string]any{})

		ch <- this.ParsePredictionOrder(orderData, outcomeObj)
		return nil

	}()
	return ch
}

